class DecryptionUtils:
    ALPHA_OFFSET_UPPER = 65
    ALPHA_OFFSET_LOWER = 97
    CHARSET_SIZE = 26
    A_ORD = ord('a')

    def __init__(self, key):
        self._key = key

    @property
    def key(self):
        return self._key

    @key.setter
    def key(self, value):
        self._key = value

    def _shift_char(self, char, shift):
        if char.isupper():
            ascii_offset = self.ALPHA_OFFSET_UPPER
        else:
            ascii_offset = self.ALPHA_OFFSET_LOWER
        return chr((ord(char) - ascii_offset - shift) % self.CHARSET_SIZE + ascii_offset)

    def caesar_decipher(self, ciphertext, shift):
        return ''.join(
            self._shift_char(char, shift) if char.isalpha() else char
            for char in ciphertext
        )

    def _get_vigenere_shift(self, key_index):
        key_char = self.key[key_index % len(self.key)].lower()
        return ord(key_char) - self.A_ORD

    def _decrypt_vigenere_char(self, char, shift):
        decrypted_char = chr((ord(char.lower()) - self.A_ORD - shift) % self.CHARSET_SIZE + self.A_ORD)
        return decrypted_char.upper() if char.isupper() else decrypted_char

    def vigenere_decipher(self, ciphertext):
        key_index = 0
        result = []
        for char in ciphertext:
            if char.isalpha():
                shift = self._get_vigenere_shift(key_index)
                result.append(self._decrypt_vigenere_char(char, shift))
                key_index += 1
            else:
                result.append(char)
        return ''.join(result)

    def rail_fence_decipher(self, encrypted_text, rails):
        fence = [['' for _ in range(len(encrypted_text))] for _ in range(rails)]

        self._fill_fence_pattern(fence, rails, len(encrypted_text))

        index = 0
        for i in range(rails):
            for j in range(len(encrypted_text)):
                if fence[i][j] == '':
                    fence[i][j] = encrypted_text[index]
                    index += 1

        return self._read_fence(fence, rails, len(encrypted_text))

    def _fill_fence_pattern(self, fence, rails, length):
        row, col = 0, 0
        direction = -1
        for _ in range(length):
            if row == 0 or row == rails - 1:
                direction = -direction
            fence[row][col] = ''
            col += 1
            row += direction

    def _read_fence(self, fence, rails, length):
        plain_text = []
        row, col = 0, 0
        direction = -1
        for _ in range(length):
            if row == 0 or row == rails - 1:
                direction = -direction
            plain_text.append(fence[row][col])
            col += 1
            row += direction
        return ''.join(plain_text)
